/**
 * The app under test, as the MCP suites reach it: its base URL, and the
 * settings routes behind Settings → MCP Server (status, switch, regenerate).
 * Every read goes to the server, so a token regenerated by one spec is the
 * token the next one uses.
 */
import type { McpServerStatusResponse } from '../../../src/shared/lib/mcp-server/mcp-server-settings-schema'

export type { McpServerStatusResponse }

export function baseUrl(): string {
  const url = process.env.E2E_BASE_URL
  if (!url) throw new Error('E2E_BASE_URL is not set: run through playwright.mcp.config.ts')
  return url
}

export function dataDir(): string {
  const dir = process.env.SUPERAGENT_DATA_DIR
  if (!dir) throw new Error('SUPERAGENT_DATA_DIR is not set: run through playwright.mcp.config.ts')
  return dir
}

export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(`${baseUrl()}${path}`, {
    ...init,
    headers: { ...(init.body ? { 'Content-Type': 'application/json' } : {}), ...init.headers },
  })
  if (!response.ok) throw new Error(`${init.method ?? 'GET'} ${path} answered ${response.status}: ${await response.text()}`)
  return response.json() as Promise<T>
}

export function mcpStatus(): Promise<McpServerStatusResponse> {
  return api('/api/mcp-server')
}

export function setMcpEnabled(enabled: boolean): Promise<McpServerStatusResponse> {
  return api('/api/mcp-server/enabled', { method: 'PUT', body: JSON.stringify({ enabled }) })
}

export function regenerateToken(): Promise<McpServerStatusResponse> {
  return api('/api/mcp-server/token/regenerate', { method: 'POST' })
}

/** The endpoint and the current token. */
export async function mcpTarget(): Promise<{ url: string; token: string }> {
  const status = await mcpStatus()
  if (!status.token) throw new Error('The server has no installation token (auth mode?)')
  return { url: status.endpointUrl, token: status.token }
}
